begin;
select no_plan();
select ok(not has_function_privilege('anon','api.execute_owner_profile_editor_server(uuid,text,jsonb)','EXECUTE'),'Anonymous denied server gateway');
select ok(not has_function_privilege('authenticated','api.execute_owner_profile_editor_server(uuid,text,jsonb)','EXECUTE'),'Browser JWT denied server gateway');
select ok(has_function_privilege('service_role','api.execute_owner_profile_editor_server(uuid,text,jsonb)','EXECUTE'),'Only server role admitted');
select ok(not has_function_privilege('service_role','api.save_current_owner_profile_text_working(jsonb)','EXECUTE'),'Original mutation still withheld');
set local role authenticated;
select throws_ok($$select api.execute_owner_profile_editor_server('26000000-0000-4000-8000-000000000001','resolve_current_owner_home_context','{}')$$,'42501',null,'Actual direct actor spoof denied');
reset role;
insert into auth.users(id,email) values('26000000-0000-4000-8000-000000000001','gateway-one@example.test'),('26000000-0000-4000-8000-000000000002','gateway-two@example.test');
create temporary table actors as select auth_user_id,owner_id from core.owner_auth_bindings where auth_user_id in('26000000-0000-4000-8000-000000000001','26000000-0000-4000-8000-000000000002');
update core.owner_onboarding_progress set current_step='preview_publish',primary_use_case='personal' where owner_id in(select owner_id from actors);
insert into core.owner_handle_namespaces(normalized_handle,owner_id,namespace_kind) select 'gateway260-'||right(auth_user_id::text,6),owner_id,'current' from actors;
update core.owners set onboarding_completed_at=now() where id in(select owner_id from actors);
insert into core.identity_working(owner_id,display_name,bio,revision) select owner_id,case when right(auth_user_id::text,1)='1' then 'First Owner' else 'Foreign Owner' end,'Private Bio',2 from actors;
insert into core.identity_layout_working(owner_id,starter_key,revision) select owner_id,'clean',1 from actors;
insert into core.identity_publications(owner_id,snapshot,identity_revision,layout_revision,connection_revision,published_at) select owner_id,'{"legacy":true}',2,1,null,now() from actors;
set local request.jwt.claims='{"role":"service_role","sub":"26000000-0000-4000-8000-000000000002"}';
set local request.jwt.claim.sub='26000000-0000-4000-8000-000000000002';
set local role service_role;
select is(api.execute_owner_profile_editor_server('26000000-0000-4000-8000-000000000001','resolve_current_owner_home_context','{}')->>'current_handle','gateway260-000001','Server subject mapped through actual binding');
select is(current_setting('request.jwt.claim.sub'),'26000000-0000-4000-8000-000000000002','Legacy subject restored');
select is(current_setting('request.jwt.claims')::jsonb,'{"role":"service_role","sub":"26000000-0000-4000-8000-000000000002"}'::jsonb,'Full service claims restored');
select is(api.execute_owner_profile_editor_server('26000000-0000-4000-8000-000000000001','resolve_current_owner_editable_identity_working_page','{"input_request":{"expected_collection_revision":null,"after_position":null}}')#>>'{profile_working,display_name}','First Owner','Reads only admitted subject work');
select is(api.execute_owner_profile_editor_server('26000000-0000-4000-8000-000000000002','resolve_current_owner_editable_identity_working_page','{"input_request":{"expected_collection_revision":null,"after_position":null}}')#>>'{profile_working,display_name}','Foreign Owner','Second subject gets own work');
select is(api.execute_owner_profile_editor_server('26000000-0000-4000-8000-000000000001','save_current_owner_profile_text_working','{"input_working":{"action":"save_profile_text_working","base_profile_revision":2,"base_text_revision":null,"profile_text_working":{"display_name":"","bio":" Raw \n Bio "}}}')->>'status','success','Persists unfinished raw Working through existing CAS');
select is(api.execute_owner_profile_editor_server('26000000-0000-4000-8000-000000000001','save_current_owner_profile_text_working','{"input_working":{"action":"save_profile_text_working","base_profile_revision":2,"base_text_revision":null,"profile_text_working":{"display_name":"stale","bio":null}}}')->>'status','stale_write','Duplicate old CAS does not overwrite');
select is(api.execute_owner_profile_editor_server('26000000-0000-4000-8000-000000000001','publish_current_onboarding','{}')->>'status','unavailable','No publication dispatch');
select is(api.execute_owner_profile_editor_server('26000000-0000-4000-8000-000000000001','resolve_current_owner_home_context','{"owner_id":"26000000-0000-4000-8000-000000000002"}')->>'status','unavailable','Extra target rejected');
reset role;
select is((select count(*)::int from core.identity_profile_text_working where owner_id=(select owner_id from actors where auth_user_id='26000000-0000-4000-8000-000000000002')),0,'Foreign Working untouched');
select ok(not exists(select 1 from core.identity_publications where snapshot<>'{"legacy":true}'::jsonb),'Published unchanged');
select is((select display_name from core.identity_working where owner_id=(select owner_id from actors where auth_user_id='26000000-0000-4000-8000-000000000001')),'First Owner','Source unchanged');
create function pg_temp.reject_profile_update() returns trigger language plpgsql as $$begin raise exception 'fixture write failure'; end;$$;
create trigger profile_editor_fixture before update on core.identity_profile_text_working for each row execute function pg_temp.reject_profile_update();
set local role service_role;
select throws_ok($q$select api.execute_owner_profile_editor_server('26000000-0000-4000-8000-000000000001','save_current_owner_profile_text_working','{"input_working":{"action":"save_profile_text_working","base_profile_revision":2,"base_text_revision":1,"profile_text_working":{"display_name":"exception","bio":null}}}')$q$,'P0001','fixture write failure','Unexpected DB exception propagates without fabricated acknowledgment');
select is(current_setting('request.jwt.claim.sub'),'26000000-0000-4000-8000-000000000002','Exception restores outer subject');
select is(current_setting('request.jwt.claims')::jsonb,'{"role":"service_role","sub":"26000000-0000-4000-8000-000000000002"}'::jsonb,'Exception restores service claims');
reset role;
drop trigger profile_editor_fixture on core.identity_profile_text_working;
update core.owners set account_state='restricted' where id=(select owner_id from actors where auth_user_id='26000000-0000-4000-8000-000000000001');
set local role service_role;
select is(api.execute_owner_profile_editor_server('26000000-0000-4000-8000-000000000001','save_current_owner_profile_text_working','{"input_working":{}}')->>'status','owner_not_eligible','Restriction still authoritative');
reset role;
select * from finish();
rollback;
